st_snippet:
(* Both channels must agree within tolerance *)
Channel_Discrepancy := (Channel_1 XOR Channel_2);

(* Discrepancy timer — allow brief transition time *)
Discrepancy_Timer(IN := Channel_Discrepancy, PT := T#100ms);

(* Fault if channels disagree for more than 100ms *)
IF Discrepancy_Timer.Q THEN
    Safety_Fault := TRUE;
END_IF;

(* Safe output only when both channels healthy and no fault *)
Safe_Output := Channel_1 AND Channel_2 AND NOT Safety_Fault;
